import * as cdk from 'aws-cdk-lib';
import { Construct } from 'constructs';
import * as apigw from 'aws-cdk-lib/aws-apigateway';

export class ApiGatewayStack extends cdk.Stack {
  constructor(scope: Construct, id: string, props?: cdk.StackProps) {
    super(scope, id, props);

    // Define a REST API
    const api = new apigw.RestApi(this, 'banking-api', {
      restApiName: 'Banking Service API',
      description: 'Exposes RESTful APIs for banking services',
      deployOptions: {
        throttlingBurstLimit: 5000,
        throttlingRateLimit: 10000
      }
    });

    // Add authentication
    const auth = new apigw.CognitoUserPoolsAuthorizer(this, 'CognitoAuth', {
      cognitoUserPools: [/* your Cognito User Pool */]
    });

    // Add a resource and method with authentication and throttling
    const resource = api.root.addResource('accounts');
    resource.addMethod('GET', new apigw.LambdaIntegration(/* your Lambda function */), {
      authorizationType: apigw.AuthorizationType.COGNITO,
      authorizer: auth
    });
  }
}

terraform.code:
provider "aws" {
  region = "us-east-1"
}

resource "aws_api_gateway_rest_api" "banking_api" {
  name        = "BankingServiceAPI"
  description = "Exposes RESTful APIs for banking services"
}

resource "aws_api_gateway_method" "get_accounts" {
  rest_api_id   = aws_api_gateway_rest_api.banking_api.id
  resource_id   = aws_api_gateway_rest_api.banking_api.root_resource_id
  http_method   = "GET"
  authorization = "COGNITO_USER_POOLS"
  authorizer_id = aws_api_gateway_authorizer.cognito_auth.id
}

resource "aws_api_gateway_authorizer" "cognito_auth" {
  name                   = "CognitoAuth"
  rest_api_id            = aws_api_gateway_rest_api.banking_api.id
  type                   = "COGNITO_USER_POOLS"
  provider_arns          = [/* your Cognito User Pool ARN */]
}

resource "aws_api_gateway_deployment" "deployment" {
  depends_on = [aws_api_gateway_method.get_accounts]
  rest_api_id = aws_api_gateway_rest_api.banking_api.id
  stage_name  = "prod"

  lifecycle {
    create_before_destroy = true
  }
}

